fn fibonacci(n: usize) -> Vec<i32> {
    // We assume n >= 2 and Fib(n) < 2^31 (i.e., fits in i32)

    let mut fibs = Vec::with_capacity(n);
    fibs.push(0); // F(0)
    fibs.push(1); // F(1)

    for i in 2..n {
        // Since the assumption guarantees no overflow,
        // we can safely add without checked arithmetic.
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }

    fibs
}